pub struct SBCContributionBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> SBCContributionBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_KIND(&mut self, KIND: sbcContributorKind) {
        self.fbb_.push_slot::<sbcContributorKind>(SBCContribution::VT_KIND, KIND, sbcContributorKind::Unspecified);
    }

    #[inline]
    pub fn add_SENSOR_ID(&mut self, SENSOR_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(SBCContribution::VT_SENSOR_ID, SENSOR_ID);
    }

    #[inline]
    pub fn add_COUNT(&mut self, COUNT: u32) {
        self.fbb_.push_slot::<u32>(SBCContribution::VT_COUNT, COUNT, 0);
    }

    #[inline]
    pub fn add_RADIAL_VARIANCE_M2(&mut self, RADIAL_VARIANCE_M2: f64) {
        self.fbb_.push_slot::<f64>(SBCContribution::VT_RADIAL_VARIANCE_M2, RADIAL_VARIANCE_M2, 0.0);
    }

    #[inline]
    pub fn add_IN_TRACK_VARIANCE_M2(&mut self, IN_TRACK_VARIANCE_M2: f64) {
        self.fbb_.push_slot::<f64>(SBCContribution::VT_IN_TRACK_VARIANCE_M2, IN_TRACK_VARIANCE_M2, 0.0);
    }

    #[inline]
    pub fn add_CROSS_TRACK_VARIANCE_M2(&mut self, CROSS_TRACK_VARIANCE_M2: f64) {
        self.fbb_.push_slot::<f64>(SBCContribution::VT_CROSS_TRACK_VARIANCE_M2, CROSS_TRACK_VARIANCE_M2, 0.0);
    }

    #[inline]
    pub fn add_VELOCITY_VARIANCE_M2_S2(&mut self, VELOCITY_VARIANCE_M2_S2: f64) {
        self.fbb_.push_slot::<f64>(SBCContribution::VT_VELOCITY_VARIANCE_M2_S2, VELOCITY_VARIANCE_M2_S2, 0.0);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> SBCContributionBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        SBCContributionBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<SBCContribution<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

