pub enum SBCOffset {}

/// Sensor Bias Contribution - exactly one arm is set.
#[derive(Copy, Clone, PartialEq)]
pub struct SBC<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for SBC<'a> {
    type Inner = SBC<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> SBC<'a> {
    pub const VT_REQUEST: ::flatbuffers::VOffsetT = 4;
    pub const VT_DIAGNOSTICS: ::flatbuffers::VOffsetT = 6;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        SBC { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args SBCArgs<'args>
    ) -> ::flatbuffers::WIPOffset<SBC<'bldr>> {
        let mut builder = SBCBuilder::new(_fbb);
        if let Some(x) = args.DIAGNOSTICS { builder.add_DIAGNOSTICS(x); }
        if let Some(x) = args.REQUEST { builder.add_REQUEST(x); }
        builder.finish()
    }

    pub fn unpack(&self) -> SBCT {
        let REQUEST = self.REQUEST().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let DIAGNOSTICS = self.DIAGNOSTICS().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        SBCT {
            REQUEST,
            DIAGNOSTICS,
        }
    }

    #[inline]
    pub fn REQUEST(&self) -> Option<SBCCovarianceRequest<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<SBCCovarianceRequest>>(SBC::VT_REQUEST, None)}
    }

    #[inline]
    pub fn DIAGNOSTICS(&self) -> Option<SBCDiagnostics<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<SBCDiagnostics>>(SBC::VT_DIAGNOSTICS, None)}
    }
}

impl ::flatbuffers::Verifiable for SBC<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<SBCCovarianceRequest>>("REQUEST", Self::VT_REQUEST, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<SBCDiagnostics>>("DIAGNOSTICS", Self::VT_DIAGNOSTICS, false)?
            .finish();
        Ok(())
    }
}

