pub fn size_prefixed_root_as_sbc(buf: &[u8]) -> Result<SBC<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<SBC>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
