pub const SBC_IDENTIFIER: &str = "$SBC";

#[inline]
pub fn sbc_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SBC_IDENTIFIER, false)
}

#[inline]
pub fn sbc_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, SBC_IDENTIFIER, true)
}

